function v3_overview(out)
E1=readtable(fullfile(out,'tables/E1_all.csv'));E2=readtable(fullfile(out,'tables/E2_all.csv'));E3=readtable(fullfile(out,'tables/E3_all.csv'));E4=readtable(fullfile(out,'tables/E4_all.csv'));P=jsondecode(fileread(fullfile(out,'reports/E1_paired_statistics.json')));a=jsondecode(fileread(fullfile(out,'reports/acceptance.json')));f=fopen(fullfile(out,'reports/综合报告.md'),'a','n','UTF-8');c=onCleanup(@()fclose(f));
raw=dir(fullfile(out,'**','sim_output.mat'));fprintf(f,'\n## 实际结果与可支持结论\n\n本批次保存%d份原始SimulationOutput，其中正式%d例、辅助%d例；辅助包含标定、预检、卸载验证和隔离回归，不计入正式分母。\n\n',numel(raw),height(E1)+height(E2)+height(E3)+height(E4),numel(raw)-height(E1)-height(E2)-height(E3)-height(E4));
fprintf(f,'实验一：A成功%d/72，B成功%d/72；共同可靠配对%d/72，其中B独有成功%d、A独有成功%d。只支持所测离散任务区域结论；不能将域外/控制异常等同物理不可达，不能外推理论最短时间。\n\n',sum(strcmp(E1.status,'SUCCESS') & ~E1.cmg),sum(strcmp(E1.status,'SUCCESS') & E1.cmg),P.comparable_pairs,P.B_only_success,P.A_only_success);
fprintf(f,'实验二：冻结增益用于全部正式PID工况。单次5/10/15°的60s全程RMSE（PID关卸载 / MPC）：');for amp=[5 10 15],S=E2(strcmp(E2.pair_id,sprintf('V2_S%02d',amp)),:);p=S(strcmp(S.method,'PID_surface_first'),:);m=S(strcmp(S.method,'MPC'),:);fprintf(f,' %d° %.4f/%.4f°；',amp,p.rmse_full_deg,m.rmse_full_deg);end;fprintf(f,'实际卸载、真实净力矩影响、后续机动代价和逐轴权限分别见E2报告，不能用H下降单独宣称恢复后续能力。MPC精确任务隔离回归通过%d。C1最后机动后段仅8s，保留窗口覆盖限制。\n\n',a.MPC_isolation_regression);
L=E3(strcmp(E3.id,'V3_L'),:);S=E3(strcmp(E3.id,'V3_S'),:);fprintf(f,'实验三：35–40s机动段RMSE，长时域%.4f°、短时域%.4f°；40–50s机动后%.4f°/%.4f°。主10°迁移阈值三组均在共同启动段越过，不能据其提前量证明任务预置。L−Z任务相对差分另作辅助证据；长时域增加预置行程并改变方向性权限，但并非普遍提高最小奇异值，不能把跟踪收益独立归因于迁移。\n\n',L.maneuver_rmse_deg,S.maneuver_rmse_deg,L.post_rmse_deg,S.post_rmse_deg);
fprintf(f,'实验四：以下为固定工程辅助判据下全部可接受频点，保留非单调现象；未列频点的连续指标和失败原因仍在E4_all.csv。不同频率经历不同飞行状态，不能解释成严格LTI带宽。\n\n|幅值°|方法|可接受/计划|可接受频点Hz|\n|---:|---|---:|---|\n');
for amp=[1 3 5],for method=1:3,if method==1,mask=~E4.cmg;label='Surface MPC';elseif method==2,mask=strcmp(E4.method,'PID_CHAIN_CMG');label='Frozen PID + CMG';else,mask=E4.cmg & strcmp(E4.method,'MPC');label='Joint MPC';end;T=E4(mask & E4.amplitude_deg==amp,:);freq=sort(T.frequency_Hz(logical(T.acceptable_tracking)));if isempty(freq),list='未观察到';else,list=char(strjoin(compose('%.2f',freq),', '));end;fprintf(f,'|%d|%s|%d/9|%s|\n',amp,label,numel(freq),list);end,end
fprintf(f,'\n已完成代码/原始数据/独立重算验收不等于所有控制任务通过。没有重整物理参数、放宽执行器约束或修改MPC最多4轮SQP要求；正式模型、默认bank及旧99份原始MAT的哈希核验见acceptance.json。新源代码布局、冲突协调和复现入口见 docs/simulink/paper_experiments/v3/。\n');
clear c;f=fopen(fullfile(out,'reports/验收状态.md'),'w','n','UTF-8');c=onCleanup(@()fclose(f));u=jsondecode(fileread(fullfile(out,'config/unit_tests.json')));fprintf(f,'# 执行与数据验收\n\n|检查|结果|\n|---|---:|\n|E1正式工况|%d/144|\n|E2正式工况|%d/21|\n|E3正式工况|%d/3|\n|E4正式工况|%d/81|\n|独立重算通过|%d|\n|单元测试类别|%d|\n|MPC隔离回归通过|%d|\n|正式模型及默认bank未改|%d|\n|旧99份原始MAT未改|%d|\n|执行与数据验收完成|%d|\n\n该验收不将失败任务改为成功：所有控制失败、域外与跟踪不佳仍在原表。E2有限整定及末次连续任务窗口覆盖不足、E3主迁移阈值受共同启动瞬态影响、E4工况随时间变化与非LTI解释限制均保留。详细数值及可支持结论见综合报告和分组报告。\n',height(E1),height(E2),height(E3),height(E4),a.independent_verification.reanalysis_pass,numel(u.tests),a.MPC_isolation_regression,a.protected_inputs_unchanged,a.old_raw_unchanged,a.paper_acceptance_complete);
end
